//! Player scores shared between the match threads of the Pixel Arena server.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};

pub type PlayerId = u32;

/// Clones share the same scores, so each match thread keeps its own handle.
#[derive(Clone, Default)]
pub struct Board {
    players: Arc<Mutex<HashMap<PlayerId, Arc<Mutex<i64>>>>>,
    total: Arc<Mutex<i64>>,
}

impl Board {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn join(&self, id: PlayerId, score: i64) {
        self.players.lock().unwrap().insert(id, Arc::new(Mutex::new(score)));
        *self.total.lock().unwrap() += score;
    }

    fn slot(&self, id: PlayerId) -> Arc<Mutex<i64>> {
        self.players.lock().unwrap()[&id].clone()
    }

    /// Adds points to a player and to the board total.
    pub fn award(&self, id: PlayerId, points: i64) {
        let slot = self.slot(id);
        // Read-modify-write under one guard; two lock() calls lost updates.
        *slot.lock().unwrap() += points;
        *self.total.lock().unwrap() += points;
    }

    /// Moves points between two players. The board total does not change.
    /// Moving points from a player to the same player changes nothing.
    pub fn transfer(&self, from: PlayerId, to: PlayerId, points: i64) {
        // Self-transfer would lock the same mutex twice and hang.
        if from == to {
            return;
        }
        let from_slot = self.slot(from);
        let to_slot = self.slot(to);
        // Lock in id order so concurrent A->B and B->A cannot deadlock.
        let (first, second) = if from < to { (&from_slot, &to_slot) } else { (&to_slot, &from_slot) };
        let mut first_guard = first.lock().unwrap();
        let mut second_guard = second.lock().unwrap();
        let (from_score, to_score) = if from < to {
            (&mut *first_guard, &mut *second_guard)
        } else {
            (&mut *second_guard, &mut *first_guard)
        };
        *from_score -= points;
        *to_score += points;
    }

    pub fn score(&self, id: PlayerId) -> i64 {
        *self.slot(id).lock().unwrap()
    }

    pub fn total(&self) -> i64 {
        *self.total.lock().unwrap()
    }
}

#[cfg(test)]
mod concurrency_tests {
    use super::*;
    use std::thread;

    #[test]
    fn concurrent_awards_are_not_lost() {
        let board = Board::new();
        board.join(1, 0);
        let handles: Vec<_> = (0..8).map(|_| { let b = board.clone(); thread::spawn(move || for _ in 0..10_000 { b.award(1, 1) }) }).collect();
        for h in handles { h.join().unwrap(); }
        assert_eq!(board.score(1), 80_000);
        assert_eq!(board.total(), 80_000);
    }

    #[test]
    fn opposite_and_self_transfers_do_not_hang() {
        let board = Board::new();
        board.join(1, 100);
        board.join(2, 100);
        board.transfer(1, 1, 5);
        let a = board.clone();
        let b = board.clone();
        let t1 = thread::spawn(move || for _ in 0..50_000 { a.transfer(1, 2, 1) });
        let t2 = thread::spawn(move || for _ in 0..50_000 { b.transfer(2, 1, 1) });
        t1.join().unwrap();
        t2.join().unwrap();
        assert_eq!(board.score(1) + board.score(2), 200);
    }
}
